let raw = ($json.choices?.[0]?.message?.content || '').trim();
const config = $('Set ForgeView Config').item.json;

const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function buildNarrationScript(parsed) {
  if (parsed.narration_script) return String(parsed.narration_script).trim();
  const scenes = [];
  for (let i = 1; i <= 7; i++) {
    if (parsed[`scene${i}`]) scenes.push(String(parsed[`scene${i}`]).trim());
  }
  return scenes.map((scene, index) => `Scene ${index + 1}: ${scene}`).join('\n');
}

let parsed;
try {
  parsed = JSON.parse(stripJsonFence(raw));
} catch (e) {
  throw new Error(`Shorts draft OpenAI output was not valid JSON: ${e.message}`);
}

parsed.title = String(parsed.title || 'ForgeView Automation Lesson #Shorts').trim();
parsed.description = String(parsed.description || '').replace(/Follow ForgeView:[\s\S]*$/i, '').trim();
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !parsed.description.includes(line)) parsed.description += `\n${line}`;
}
parsed.description = parsed.description.replace(/\n{3,}/g, '\n\n').trim();
parsed.narration_script = buildNarrationScript(parsed);
if (!Array.isArray(parsed.tags)) {
  parsed.tags = ['AI automation', 'trading bots', 'n8n', 'build in public', 'ForgeViewAI'];
}

raw = JSON.stringify(parsed, null, 2);

const message = `YOUTUBE SHORTS DRAFT - REVIEW MANUALLY\n\n${raw}\n\nProject: ${config.BRAND_NAME}`;

return [{
  json: {
    shorts_raw: raw,
    shorts_json: parsed,
    shorts_message: message,
    x_drafts_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID
  }
}];

const config = $('Set ForgeView Config').item.json;
const draft = $('Format Shorts Draft').item.json;

function stripJsonFence(value) {
  return String(value || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

let shortsJson = draft.shorts_json;
if (!shortsJson) {
  try {
    shortsJson = JSON.parse(stripJsonFence(draft.shorts_raw));
  } catch (error) {
    throw new Error(`Shorts draft is not valid JSON: ${error.message}`);
  }
}

let title = String(shortsJson.title || 'ForgeView Automation Lesson #Shorts').replace(/\s+/g, ' ').trim();
if (!/#Shorts/i.test(title)) title = `${title} #Shorts`;
if (title.length > 100) title = title.slice(0, 97).trimEnd() + '...';

let description = String(shortsJson.description || '').trim();
if (!description) {
  description = 'A ForgeView build-in-public lesson from AI automation, trading bots, and workflow reliability.';
}
const requiredDescriptionBlock = `#Shorts\n\nTelegram:\nhttps://t.me/ForgeViewCom\n\nX:\nhttps://x.com/ForgeViewX`;
for (const line of requiredDescriptionBlock.split('\n')) {
  if (line && !description.includes(line)) description += `\n${line}`;
}
description = description.replace(/\n{3,}/g, '\n\n').trim();

const tags = Array.isArray(shortsJson.tags)
  ? shortsJson.tags.map(String).filter(Boolean)
  : ['AI automation', 'trading bots', 'n8n', 'build in public', 'ForgeViewAI'];
const narrationScript = String(shortsJson.narration_script || '').trim();

return [{
  json: {
    draft_chat_id: config.X_DRAFTS_TELEGRAM_CHAT_ID,
    youtube_channel_handle: '@ForgeViewGrowth',
    privacyStatus: 'private',
    categoryId: '28',
    title,
    description,
    tags,
    tags_text: tags.join(', '),
    narration_script: narrationScript,
    shorts_json: shortsJson,
    local_project_root: 'D:\\ForgeViewAI',
    shorts_generator_dir: 'D:\\ForgeViewAI\\content\\video\\shorts-generator',
    output_path: 'D:\\ForgeViewAI\\output\\media\\videos\\short.mp4'
  }
}];

const prepared = $('Prepare Shorts Generator Payload').item.json;
const bridge = $json || {};
let videoUrl = bridge.video_url || bridge.download_url || bridge.mp4_url;

if (!videoUrl) {
  throw new Error('Local Shorts Generator bridge did not return video_url/download_url/mp4_url for the generated MP4.');
}

if (/^http:\/\/(localhost|127\.0\.0\.1):/i.test(videoUrl)) {
  const bridgeUrl = 'https://FORGEVIEW_BRIDGE_URL/forgeview/render-short';
  if (bridgeUrl.includes('FORGEVIEW_BRIDGE_URL')) {
    throw new Error('BRIDGE URL NOT CONFIGURED');
  }
  videoUrl = bridgeUrl.replace(/\/forgeview\/render-short\/?$/, '/files/short.mp4');
}

return [{
  json: {
    ...prepared,
    bridge_status: bridge.status || (bridge.ok ? 'ok' : 'unknown'),
    bridge_message: bridge.message || '',
    bridge_video_path: bridge.video_path || '',
    generated_video_url: videoUrl
  }
}];

const upload = $json;
const prepared = $('Prepare Shorts Generator Payload').item.json;
const videoId = upload.id || upload.videoId || upload.snippet?.resourceId?.videoId || '';
const url = videoId ? `https://www.youtube.com/watch?v=${videoId}` : 'URL unavailable';

return [{
  json: {
    draft_chat_id: prepared.draft_chat_id,
    video_id: videoId,
    video_url: url,
    privacyStatus: 'private',
    title: prepared.title,
    confirmation_text: `UPLOAD SUCCESS\n\nVideo ID:\n${videoId || 'unknown'}\n\nURL:\n${url}\n\nPrivacy:\nprivate`
  }
}];
